+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Cat FAQ</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      --bg: #0d1117;
+      --panel: #151b23;
+      --panel-strong: #1f2937;
+      --text: #f3f7fb;
+      --muted: #aab8c5;
+      --accent: #9ddcff;
+      --accent-strong: #57c7ff;
+      --border: rgba(157, 220, 255, 0.2);
+      --shadow: rgba(0, 0, 0, 0.35);
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      color: var(--text);
+      background:
+        radial-gradient(circle at top left, rgba(87, 199, 255, 0.16), transparent 32rem),
+        linear-gradient(135deg, #0d1117 0%, #111827 48%, #0a0f1a 100%);
+      line-height: 1.6;
+    }
+
+    .page {
+      width: min(920px, calc(100% - 32px));
+      margin: 0 auto;
+      padding: 64px 0;
+    }
+
+    .hero {
+      margin-bottom: 32px;
+      padding: 36px;
+      border: 1px solid var(--border);
+      border-radius: 28px;
+      background: linear-gradient(145deg, rgba(31, 41, 55, 0.94), rgba(21, 27, 35, 0.86));
+      box-shadow: 0 24px 70px var(--shadow);
+    }
+
+    .eyebrow {
+      margin: 0 0 12px;
+      color: var(--accent);
+      font-size: 0.82rem;
+      font-weight: 800;
+      letter-spacing: 0.18em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      max-width: 13ch;
+      font-size: clamp(2.5rem, 8vw, 5rem);
+      line-height: 0.95;
+      letter-spacing: -0.06em;
+    }
+
+    .intro {
+      max-width: 62ch;
+      margin: 20px 0 0;
+      color: var(--muted);
+      font-size: 1.08rem;
+    }
+
+    .faq-list {
+      display: grid;
+      gap: 16px;
+    }
+
+    .example {
+      overflow: hidden;
+      border: 1px solid var(--border);
+      border-radius: 22px;
+      background: rgba(21, 27, 35, 0.82);
+      box-shadow: 0 16px 44px rgba(0, 0, 0, 0.24);
+    }
+
+    .question {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      width: 100%;
+      gap: 20px;
+      padding: 22px 24px;
+      border: 0;
+      color: var(--text);
+      background: transparent;
+      font: inherit;
+      font-size: 1.1rem;
+      font-weight: 750;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question:hover {
+      background: rgba(157, 220, 255, 0.07);
+    }
+
+    .question:focus-visible {
+      outline: 3px solid var(--accent-strong);
+      outline-offset: -6px;
+    }
+
+    .icon {
+      display: inline-grid;
+      flex: 0 0 32px;
+      width: 32px;
+      height: 32px;
+      place-items: center;
+      border: 1px solid rgba(157, 220, 255, 0.36);
+      border-radius: 999px;
+      color: var(--accent);
+      background: rgba(157, 220, 255, 0.08);
+      font-size: 1.3rem;
+      line-height: 1;
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .question[aria-expanded="true"] .icon {
+      transform: rotate(45deg);
+      background: rgba(87, 199, 255, 0.18);
+    }
+
+    .details {
+      padding: 0 24px 24px;
+      color: var(--muted);
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      max-width: 70ch;
+      margin: 0;
+      padding-top: 2px;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        width: min(100% - 24px, 920px);
+        padding: 28px 0;
+      }
+
+      .hero {
+        padding: 26px;
+        border-radius: 22px;
+      }
+
+      .question {
+        padding: 18px;
+      }
+
+      .details {
+        padding: 0 18px 20px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <div id="root"></div>
+
+  <script>
+    const faqs = [
+      {
+        question: "Why do cats knead with their paws?",
+        answer: "Kneading is a comforting behavior kittens use while nursing. Adult cats often keep doing it when they feel relaxed, secure, or happy."
+      },
+      {
+        question: "How much sleep do cats need?",
+        answer: "Most cats sleep between 12 and 16 hours a day. Kittens, seniors, and very active cats may need even more rest."
+      },
+      {
+        question: "Why does my cat chirp at birds?",
+        answer: "Chirping is usually excitement or focused hunting behavior. Your cat may be reacting to prey-like movement outside the window."
+      },
+      {
+        question: "Should indoor cats still see a veterinarian?",
+        answer: "Yes. Indoor cats still need preventive care, dental checks, vaccines recommended by your veterinarian, and help catching health changes early."
+      },
+      {
+        question: "How can I keep a cat entertained indoors?",
+        answer: "Offer climbing spaces, scratching posts, puzzle feeders, window perches, rotating toys, and daily interactive play with wand or chase toys."
+      }
+    ];
+
+    function App() {
+      return `
+        <main class="page">
+          ${Hero()}
+          ${FAQList({ items: faqs })}
+        </main>
+      `;
+    }
+
+    function Hero() {
+      return `
+        <header class="hero">
+          <p class="eyebrow">Cat care basics</p>
+          <h1>Frequently asked questions about cats</h1>
+          <p class="intro">
+            Quick answers for common feline behaviors, health habits, and enrichment needs.
+            Select a question to reveal the answer.
+          </p>
+        </header>
+      `;
+    }
+
+    function FAQList({ items }) {
+      return `
+        <section class="faq-list" aria-label="Cat frequently asked questions">
+          ${items.map((item, index) => FAQItem({ item, index })).join("")}
+        </section>
+      `;
+    }
+
+    function FAQItem({ item, index }) {
+      const buttonId = `question-${index + 1}`;
+      const detailsId = `answer-${index + 1}`;
+
+      return `
+        <div class="example">
+          <h2>
+            <button
+              class="question"
+              id="${buttonId}"
+              type="button"
+              aria-expanded="false"
+              aria-controls="${detailsId}"
+            >
+              <span>${item.question}</span>
+              <span class="icon" aria-hidden="true">+</span>
+            </button>
+          </h2>
+          <div class="details" id="${detailsId}" role="region" aria-labelledby="${buttonId}" hidden>
+            <p>${item.answer}</p>
+          </div>
+        </div>
+      `;
+    }
+
+    function bindDisclosureControls() {
+      document.querySelectorAll(".question").forEach((button) => {
+        button.addEventListener("click", () => {
+          const details = document.getElementById(button.getAttribute("aria-controls"));
+          const isExpanded = button.getAttribute("aria-expanded") === "true";
+
+          button.setAttribute("aria-expanded", String(!isExpanded));
+          details.hidden = isExpanded;
+        });
+      });
+    }
+
+    document.getElementById("root").innerHTML = App();
+    bindDisclosureControls();
+  </script>
+</body>
+</html>
*** End Patch
', intention_summary=None, mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.CUSTOM: 'custom'>)

